# Hermes Agent Installer - Windows PowerShell\n# Version: 0.21.2\n\n$ErrorActionPreference = \"Stop\"\n\nWrite-Host \"`nHermes Agent v0.21.2 Installer\" -ForegroundColor Cyan\nWrite-Host \"Built by Nous Research`n\" -ForegroundColor Cyan\n\n$HERMES_HOME = if ($env:HERMES_HOME) { $env:HERMES_HOME } else { \"$env:LOCALAPPDATA\\hermes\" }\n\nWrite-Host \"✓ Hermes home: $HERMES_HOME\" -ForegroundColor Green\n\nNew-Item -ItemType Directory -Force -Path $HERMES_HOME | Out-Null\n\n# Check Python\nif (-not (Get-Command python -ErrorAction SilentlyContinue)) {\n    Write-Host \"⚠ Installing Python 3.11...\" -ForegroundColor Yellow\n    $pythonUrl = \"https://www.python.org/ftp/python/3.11.9/python-3.11.9-amd64.exe\"\n    $pythonInstaller = \"$env:TEMP\\python-installer.exe\"\n    Invoke-WebRequest -Uri $pythonUrl -OutFile $pythonInstaller\n    & $pythonInstaller /quiet InstallAllUsers=1 PrependPath=1\n    Remove-Item $pythonInstaller\n}\n\nWrite-Host \"✓ Python installed\" -ForegroundColor Green\n\n# Install uv\nif (-not (Get-Command uv -ErrorAction SilentlyContinue)) {\n    Write-Host \"⚠ Installing uv...\" -ForegroundColor Yellow\n    powershell -Command \"irm https://astral.sh/uv/install.sh | iex\"\n}\n\nWrite-Host \"✓ uv installed\" -ForegroundColor Green\n\n# Git\nif (-not (Get-Command git -ErrorAction SilentlyContinue)) {\n    Write-Host \"⚠ Installing Git...\" -ForegroundColor Yellow\n    choco install git -y 2>$null || (\n        $gitUrl = \"https://github.com/git-for-windows/git/releases/download/v2.42.0.windows.2/Git-2.42.0.2-64-bit.exe\"\n        $gitInstaller = \"$env:TEMP\\git-installer.exe\"\n        Invoke-WebRequest -Uri $gitUrl -OutFile $gitInstaller\n        & $gitInstaller /SILENT\n        Remove-Item $gitInstaller\n    )\n}\n\nWrite-Host \"✓ Git installed\" -ForegroundColor Green\n\n# Clone\nif (-not (Test-Path \"$HERMES_HOME\\hermes-agent\")) {\n    Write-Host \"⚠ Cloning Hermes...\" -ForegroundColor Yellow\n    git clone --depth 1 https://github.com/Tahar0061/hermes-agent-build.git \"$HERMES_HOME\\hermes-agent\"\n} else {\n    Write-Host \"⚠ Updating...\" -ForegroundColor Yellow\n    Push-Location \"$HERMES_HOME\\hermes-agent\"\n    git pull origin main\n    Pop-Location\n}\n\nWrite-Host \"✓ Repository ready\" -ForegroundColor Green\n\n# Venv\nWrite-Host \"⚠ Setting up environment...\" -ForegroundColor Yellow\nuv venv \"$HERMES_HOME\\venv\" --python 3.11\n\n# Install\nWrite-Host \"⚠ Installing Hermes (this may take a few minutes)...\" -ForegroundColor Yellow\n& \"$HERMES_HOME\\venv\\Scripts\\Activate.ps1\"\nuv pip install -e \"$HERMES_HOME\\hermes-agent[all]\"\n\nWrite-Host \"✓ Installation complete\" -ForegroundColor Green\n\n# Add to PATH\n[Environment]::SetEnvironmentVariable(\"PATH\", \"$HERMES_HOME\\venv\\Scripts;$env:PATH\", \"User\")\n\nWrite-Host \"`nInstallation Complete! 🎉\" -ForegroundColor Green\nWrite-Host \"`nNext steps:\" -ForegroundColor Yellow\nWrite-Host \"  1. Restart PowerShell\" -ForegroundColor Cyan\nWrite-Host \"  2. Start: hermes\" -ForegroundColor Cyan\nWrite-Host \"  3. Setup: hermes setup\" -ForegroundColor Cyan\nWrite-Host \"`nDocs: https://hermes-agent.nousresearch.com/docs\" -ForegroundColor Blue\nWrite-Host \"Discord: https://discord.gg/NousResearch\" -ForegroundColor Blue\n"